   848  /* Read the next archive header.  */
   849  int
   850  internal_function
   851  __libelf_next_arhdr_wrlock (Elf *elf)
   852  {
   853    struct ar_hdr *ar_hdr;
   854    Elf_Arhdr *elf_ar_hdr;
   855
   856    if (elf->map_address != NULL)
   857      {
   858        /* See whether this entry is in the file.  */
   859        if (unlikely ((size_t) elf->state.ar.offset
   860                      > elf->start_offset + elf->maximum_size
   861                      || (elf->start_offset + elf->maximum_size
   862                          - elf->state.ar.offset) < sizeof (struct ar_hdr)))
   863          {
   864            /* This record is not anymore in the file.  */
   865            __libelf_seterrno (ELF_E_RANGE);
   866            return -1;
   867          }
   868        ar_hdr = (struct ar_hdr *) (elf->map_address + elf->state.ar.offset);
   869      }
   870    else
   871      {
   872        ar_hdr = &elf->state.ar.ar_hdr;
   873
   874        if (unlikely (pread_retry (elf->fildes, ar_hdr, sizeof (struct ar_hdr),
   875                                   elf->state.ar.offset)
   876                      != sizeof (struct ar_hdr)))
   877          {
   878            /* Something went wrong while reading the file.  */
   879            __libelf_seterrno (ELF_E_RANGE);
   880            return -1;
   881          }
   882      }
   883
   884    /* One little consistency check.  */
   885    if (unlikely (memcmp (ar_hdr->ar_fmag, ARFMAG, 2) != 0))
   886      {
   887        /* This is no valid archive.  */
   888        __libelf_seterrno (ELF_E_ARCHIVE_FMAG);
   889        return -1;
   890      }
   891
   892    /* Copy the raw name over to a NUL terminated buffer.  */
   893    *((char *) mempcpy (elf->state.ar.raw_name, ar_hdr->ar_name, 16)) = '\0';
   894
   895    elf_ar_hdr = &elf->state.ar.elf_ar_hdr;
   896
   897    /* Now convert the `struct ar_hdr' into `Elf_Arhdr'.
   898       Determine whether this is a special entry.  */
   899    if (ar_hdr->ar_name[0] == '/')
   900      {
   901        if (ar_hdr->ar_name[1] == ' '
   902            && memcmp (ar_hdr->ar_name, "/               ", 16) == 0)
   903          /* This is the index.  */
   904          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "/", 2);
   905        else if (ar_hdr->ar_name[1] == 'S'
   906                 && memcmp (ar_hdr->ar_name, "/SYM64/         ", 16) == 0)
   907          /* 64-bit index.  */
   908          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "/SYM64/", 8);
   909        else if (ar_hdr->ar_name[1] == '/'
   910                 && memcmp (ar_hdr->ar_name, "//              ", 16) == 0)
   911          /* This is the array with the long names.  */
   912          elf_ar_hdr->ar_name = memcpy (elf->state.ar.ar_name, "//", 3);
   913        else if (likely  (isdigit (ar_hdr->ar_name[1])))
   914          {
   915            size_t offset;
   916
   917            /* This is a long name.  First we have to read the long name
   918               table, if this hasn't happened already.  */
   919            if (unlikely (elf->state.ar.long_names == NULL
   920                          && read_long_names (elf) == NULL))
   921              {
   922                /* No long name table although it is reference.  The archive is
   923                   broken.  */
   924                __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   925                return -1;
   926              }
   927
   928            offset = atol (ar_hdr->ar_name + 1);
   929            if (unlikely (offset >= elf->state.ar.long_names_len))
   930              {
   931                /* The index in the long name table is larger than the table.  */
   932                __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   933                return -1;
   934              }
   935            elf_ar_hdr->ar_name = elf->state.ar.long_names + offset;
   936          }
   937        else
   938          {
   939            /* This is none of the known special entries.  */
   940            __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   941            return -1;
   942          }
   943      }
   944    else
   945      {
   946        char *endp;
   947
   948        /* It is a normal entry.  Copy over the name.  */
   949        endp = (char *) memccpy (elf->state.ar.ar_name, ar_hdr->ar_name,
   950                                 '/', 16);
   951        if (endp != NULL)
   952          endp[-1] = '\0';
   953        else
   954          {
   955            /* In the old BSD style of archive, there is no / terminator.
   956               Instead, there is space padding at the end of the name.  */
   957            size_t i = 15;
   958            do
   959              elf->state.ar.ar_name[i] = '\0';
   960            while (i > 0 && elf->state.ar.ar_name[--i] == ' ');
   961          }
   962
   963        elf_ar_hdr->ar_name = elf->state.ar.ar_name;
   964      }
   965
   966    if (unlikely (ar_hdr->ar_size[0] == ' '))
   967      /* Something is really wrong.  We cannot live without a size for
   968         the member since it will not be possible to find the next
   969         archive member.  */
   970      {
   971        __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
   972        return -1;
   973      }
   974
   975    /* Since there are no specialized functions to convert ASCII to
   976       time_t, uid_t, gid_t, mode_t, and off_t we use either atol or
   977       atoll depending on the size of the types.  We are also prepared
   978       for the case where the whole field in the `struct ar_hdr' is
   979       filled in which case we cannot simply use atol/l but instead have
   980       to create a temporary copy.  */
   981
   982  #define INT_FIELD(FIELD)                                                      \
   983    do                                                                          \
   984      {                                                                         \
   985        char buf[sizeof (ar_hdr->FIELD) + 1];                                   \
   986        const char *string = ar_hdr->FIELD;                                     \
   987        if (ar_hdr->FIELD[sizeof (ar_hdr->FIELD) - 1] != ' ')                   \
   988          {                                                                     \
   989            *((char *) mempcpy (buf, ar_hdr->FIELD, sizeof (ar_hdr->FIELD)))  \
   990              = '\0';                                                           \
   991            string = buf;                                                       \
   992          }                                                                     \
   993        if (sizeof (elf_ar_hdr->FIELD) <= sizeof (long int))                    \
   994          elf_ar_hdr->FIELD = (__typeof (elf_ar_hdr->FIELD)) atol (string);     \
   995        else                                                                    \
   996          elf_ar_hdr->FIELD = (__typeof (elf_ar_hdr->FIELD)) atoll (string);    \
   997      }                                                                         \
   998    while (0)
   999
  1000    INT_FIELD (ar_date);
  1001    INT_FIELD (ar_uid);
  1002    INT_FIELD (ar_gid);
  1003    INT_FIELD (ar_mode);
  1004    INT_FIELD (ar_size);
  1005
  1006    if (elf_ar_hdr->ar_size < 0)
  1007      {
  1008        __libelf_seterrno (ELF_E_INVALID_ARCHIVE);
  1009        return -1;
  1010      }
  1011
  1012    /* Truncated file?  */
  1013    size_t maxsize;
  1014    maxsize = (elf->start_offset + elf->maximum_size
  1015               - elf->state.ar.offset - sizeof (struct ar_hdr));
  1016    if ((size_t) elf_ar_hdr->ar_size > maxsize)
  1017      elf_ar_hdr->ar_size = maxsize;
  1018
  1019    return 0;
  1020  }
